      hu: ["Szöveteket és fonalakat gyárt.", "Ambato 'a virágok és gyümölcsök városa' és a bőripar központja.", "Fontos beszállító a helyi ruhaipar számára."],
      ro: ["Produce țesături și fire.", "Ambato este cunoscut ca 'Orașul Florilor și Fructelor' și al pielăriei.", "Furnizor important pentru industria locală de îmbrăcăminte."],
